-- ES/DE/FR translations for the rest of the UK's deep-dive content.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol descentralizado de cuatro esquinas (confirmado)', 'Esta página de análisis refleja la orientación pública disponible a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El detalle técnico del mandato del Reino Unido sigue genuinamente sin confirmar a la espera del Presupuesto de 2026 — trate todo lo que no esté marcado explícitamente como "Confirmado" arriba como una expectativa razonable más que un hecho consolidado, y consulte GOV.UK directamente una vez se publique la hoja de ruta completa.', 'El Reino Unido ha pasado de "voluntario y fragmentado" a "obligatorio con una red confirmada" en menos de dos años — pero el detalle fino todavía se está redactando.', 'El formato de archivo exacto es una de las pocas preguntas genuinamente abiertas que quedan — pero la dirección del avance es inconfundible.', 'La dirección del mandato del Reino Unido está confirmada — Peppol, cuatro esquinas, sin reporte en tiempo real, abril de 2029 — pero los estándares técnicos detallados, el alcance exacto y cualquier implementación por fases aún no se han publicado; la HMRC se ha comprometido a presentar una hoja de ruta de implementación completa en el Presupuesto de 2026 (noviembre). El Reino Unido ha elegido deliberadamente el extremo opuesto del espectro respecto a Polonia o Francia aquí — sin autoridad de compensación, y explícitamente sin ningún envío de datos de transacciones en vivo a la HMRC en el lanzamiento.', 'Dado que los estándares detallados aún no se han publicado, el "registro" hoy en realidad se trata de posicionarse bien antes del Presupuesto de 2026 — no de inscribirse en nada.', 'Todavía no existe ningún marco de sanciones — no hay nada que aplicar hasta que el propio mandato entre en vigor. Estas son las incertidumbres prácticas que vale la pena seguir en su lugar.' FROM countries WHERE name_en = 'United Kingdom';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dezentrales Vier-Ecken-Peppol (bestätigt)', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Das technische Detail der britischen Vorgabe ist bis zum Haushalt 2026 genuin unbestätigt — behandeln Sie alles, was oben nicht ausdrücklich als "Bestätigt" gekennzeichnet ist, als vernünftige Erwartung statt als feststehende Tatsache, und prüfen Sie GOV.UK direkt, sobald die vollständige Roadmap veröffentlicht ist.', 'Das Vereinigte Königreich hat sich in weniger als zwei Jahren von "freiwillig und fragmentiert" zu "verpflichtend mit bestätigtem Netzwerk" entwickelt — doch die Feinheiten werden noch ausgearbeitet.', 'Das genaue Dateiformat ist eine der wenigen genuin offenen Fragen, die noch bleiben — doch die Richtung ist unverkennbar.', 'Die Richtung der britischen Vorgabe ist bestätigt — Peppol, Vier-Ecken-Modell, keine Echtzeitmeldung, April 2029 — doch die detaillierten technischen Standards, der genaue Anwendungsbereich und eine etwaige Staffelung sind noch nicht veröffentlicht; die HMRC hat sich zu einer vollständigen Umsetzungs-Roadmap beim Haushalt 2026 (November) verpflichtet. Das Vereinigte Königreich hat hier bewusst das entgegengesetzte Ende des Spektrums im Vergleich zu Polen oder Frankreich gewählt — keine Clearing-Behörde, und ausdrücklich keine Live-Transaktionsdatenübermittlung an die HMRC beim Start.', 'Da detaillierte Standards noch nicht veröffentlicht sind, geht es bei der "Registrierung" heute eigentlich darum, sich gut vor dem Haushalt 2026 zu positionieren — nicht darum, sich irgendwo anzumelden.', 'Es gibt noch keinen Sanktionsrahmen — es gibt nichts durchzusetzen, bis die Vorgabe selbst in Kraft tritt. Dies sind die praktischen Unsicherheiten, die es stattdessen zu verfolgen lohnt.' FROM countries WHERE name_en = 'United Kingdom';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Peppol décentralisé à quatre coins (confirmé)', 'Cette analyse par pays reflète les directives publiques disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le détail technique de l''obligation britannique reste véritablement non confirmé dans l''attente du Budget 2026 — traitez tout ce qui n''est pas explicitement marqué « Confirmé » ci-dessus comme une attente raisonnable plutôt qu''un fait établi, et consultez GOV.UK directement une fois la feuille de route complète publiée.', 'Le Royaume-Uni est passé de « volontaire et fragmenté » à « obligatoire avec un réseau confirmé » en moins de deux ans — mais le détail fin est encore en cours de rédaction.', 'Le format de fichier exact est l''une des rares questions véritablement ouvertes restantes — mais la direction est incontestable.', 'L''orientation de l''obligation britannique est confirmée — Peppol, quatre coins, aucune déclaration en temps réel, avril 2029 — mais les normes techniques détaillées, le champ d''application exact et un éventuel déploiement par phases ne sont pas encore publiés ; la HMRC s''est engagée à présenter une feuille de route de mise en œuvre complète lors du Budget 2026 (novembre). Le Royaume-Uni a délibérément choisi ici l''extrémité opposée du spectre par rapport à la Pologne ou la France — aucune autorité de contrôle, et explicitement aucune transmission de données de transaction en direct à la HMRC au lancement.', 'Les normes détaillées n''étant pas encore publiées, « l''inscription » aujourd''hui consiste en réalité à bien se positionner avant le Budget 2026 — pas à s''inscrire à quoi que ce soit.', 'Aucun cadre de sanctions n''existe encore — il n''y a rien à appliquer tant que l''obligation elle-même n''entre pas en vigueur. Voici les incertitudes pratiques qu''il vaut la peine de suivre à la place.' FROM countries WHERE name_en = 'United Kingdom';

