INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'Lo que está confirmado', '[["Estándar de red", "Peppol"], ["Base pública existente", "BS EN 16931 (Ley de Contratación Pública de 2023)"], ["Formato actual del NHS", "Peppol BIS Billing 3.0"]]', 'Dado que los proveedores del NHS ya usan Peppol BIS Billing 3.0 y los organismos públicos ya aceptan EN 16931, el punto de llegada más probable es que el mandato general simplemente amplíe estos estándares existentes — pero esto aún no está confirmado oficialmente para el mandato B2B más amplio.', NULL, 'Confirmado' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'What''s confirmed';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Was bestätigt ist', '[["Netzwerkstandard", "Peppol"], ["Bestehende öffentliche Grundlage", "BS EN 16931 (Public Procurement Act 2023)"], ["Aktuelles NHS-Format", "Peppol BIS Billing 3.0"]]', 'Da NHS-Lieferanten bereits Peppol BIS Billing 3.0 nutzen und öffentliche Stellen bereits EN 16931 akzeptieren, ist der wahrscheinlichste Landepunkt, dass die allgemeine Vorgabe diese bestehenden Standards einfach erweitert — dies ist jedoch für die breitere B2B-Vorgabe noch nicht offiziell bestätigt.', NULL, 'Bestätigt' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'What''s confirmed';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'Ce qui est confirmé', '[["Norme réseau", "Peppol"], ["Base publique existante", "BS EN 16931 (Public Procurement Act 2023)"], ["Format actuel du NHS", "Peppol BIS Billing 3.0"]]', 'Étant donné que les fournisseurs du NHS utilisent déjà Peppol BIS Billing 3.0 et que les organismes publics acceptent déjà l''EN 16931, le point d''aboutissement le plus probable est que l''obligation générale étende simplement ces normes existantes — mais cela n''est pas encore officiellement confirmé pour l''obligation B2B plus large.', NULL, 'Confirmé' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'What''s confirmed';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'Lo que está pendiente', '[["Formato de archivo exacto", "UBL frente a un CIUS específico del Reino Unido — sin decidir"], ["Modelo de acreditación", "Aún no publicado"], ["Detalles del alcance", "Umbrales exactos de tamaño de empresa, si se hace por fases"]]', 'La HMRC ha declarado explícitamente que trabajará con las partes interesadas para sopesar la adopción de un estándar internacional existente frente al diseño de algo específico del Reino Unido — no construya todavía contra una versión de esquema específica.', NULL, 'Pendiente del Presupuesto 2026' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'What''s pending';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Was aussteht', '[["Genaues Dateiformat", "UBL gegenüber einer UK-spezifischen CIUS — unentschieden"], ["Akkreditierungsmodell", "Noch nicht veröffentlicht"], ["Details zum Anwendungsbereich", "Genaue Unternehmensgrößenschwellen, falls gestaffelt"]]', 'Die HMRC hat ausdrücklich erklärt, mit Interessenvertretern abzuwägen, ob ein bestehender internationaler Standard übernommen oder etwas UK-spezifisches entworfen wird — bauen Sie noch nicht auf eine bestimmte Schemaversion.', NULL, 'Ausstehend bis Haushalt 2026' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'What''s pending';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'Ce qui est en attente', '[["Format de fichier exact", "UBL contre un CIUS propre au Royaume-Uni — non tranché"], ["Modèle d''accréditation", "Pas encore publié"], ["Détails du champ d''application", "Seuils exacts de taille d''entreprise, en cas de déploiement par phases"]]', 'La HMRC a explicitement déclaré qu''elle travaillerait avec les parties prenantes pour évaluer l''adoption d''une norme internationale existante par rapport à la conception de quelque chose de propre au Royaume-Uni — ne construisez pas encore contre une version de schéma spécifique.', NULL, 'En attente du Budget 2026' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'What''s pending';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'Contenido base actual de la factura de IVA', '[["Base legal", "Ley del IVA de 1994 / Reglamento del IVA de 1995"], ["Campos obligatorios hoy", "Datos del proveedor/cliente, número de registro de IVA, fecha/número de factura, descripción, importes neto/IVA/bruto"]]', 'Cualquiera que sea el formato estructurado que finalmente se adopte, tendrá que transportar todos los datos ya exigidos para una factura de IVA británica válida — no se espera que cambie nada de ese contenido legal subyacente.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'Current baseline VAT invoice content';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Aktueller Basisinhalt der Umsatzsteuerrechnung', '[["Rechtsgrundlage", "VAT Act 1994 / VAT Regulations 1995"], ["Heute erforderliche Pflichtfelder", "Lieferanten-/Kundendaten, Umsatzsteuer-Registrierungsnummer, Rechnungsdatum/-nummer, Beschreibung, Netto-/USt-/Bruttobeträge"]]', 'Welches strukturierte Format auch immer letztlich landet, es muss alle bereits für eine gültige britische Umsatzsteuerrechnung erforderlichen Daten tragen — an diesem zugrunde liegenden gesetzlichen Inhalt wird sich voraussichtlich nichts ändern.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'Current baseline VAT invoice content';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'Contenu de base actuel de la facture de TVA', '[["Base légale", "VAT Act 1994 / VAT Regulations 1995"], ["Champs obligatoires aujourd''hui", "Détails fournisseur/client, numéro d''immatriculation à la TVA, date/numéro de facture, description, montants net/TVA/brut"]]', 'Quel que soit le format structuré qui finira par s''imposer, il devra porter toutes les données déjà exigées pour une facture de TVA britannique valable — on ne s''attend à aucun changement de ce contenu légal sous-jacent.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'Current baseline VAT invoice content';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'La posición voluntaria actual', '[["Facturación electrónica B2B", "Voluntaria, por acuerdo mutuo"], ["Proveedores del NHS", "Peppol BIS 3.0 obligatorio desde 2019"], ["Otros organismos públicos", "Deben aceptar facturas electrónicas EN 16931 (solo recepción)"]]', 'Si ya comercia con el NHS o con otro organismo público, es probable que hoy tenga más preparación Peppol de lo que podría suponer — esa infraestructura debería trasladarse al mandato general.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'Today''s voluntary position';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Die heutige freiwillige Position', '[["B2B-E-Invoicing", "Freiwillig, im gegenseitigen Einvernehmen"], ["NHS-Lieferanten", "Peppol BIS 3.0 seit 2019 verpflichtend"], ["Andere öffentliche Stellen", "Müssen EN-16931-E-Rechnungen akzeptieren (nur Empfang)"]]', 'Wenn Sie bereits mit dem NHS oder einer anderen öffentlichen Stelle handeln, verfügen Sie heute wahrscheinlich über mehr Peppol-Bereitschaft, als Sie vielleicht annehmen — diese Infrastruktur sollte in die allgemeine Vorgabe übernommen werden.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'Today''s voluntary position';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'La position volontaire actuelle', '[["Facturation électronique B2B", "Volontaire, d''un commun accord"], ["Fournisseurs du NHS", "Peppol BIS 3.0 obligatoire depuis 2019"], ["Autres organismes publics", "Doivent accepter les factures électroniques EN 16931 (réception uniquement)"]]', 'Si vous commercez déjà avec le NHS ou un autre organisme public, vous disposez probablement aujourd''hui d''une préparation Peppol plus avancée que vous ne le pensez — cette infrastructure devrait se reporter sur l''obligation générale.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'file_format' AND dct.title = 'Today''s voluntary position';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo", "Peppol de cuatro esquinas (descentralizado)"], ["Autoridad de compensación", "Ninguna"], ["Régimen comparable", "Modelo de primera fase de Bélgica (2026)"]]', 'Esto mantiene al Reino Unido ampliamente interoperable con los socios comerciales de la UE a pesar de que el Brexit elimina cualquier obligación legal de alinearse con el marco ViDA de la UE — una elección deliberada para preservar la compatibilidad transfronteriza.', NULL, 'Confirmado' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Network model';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Modell", "Vier-Ecken-Peppol (dezentralisiert)"], ["Clearing-Behörde", "Keine"], ["Vergleichbares Regime", "Belgiens Modell der ersten Phase (2026)"]]', 'Dies hält das Vereinigte Königreich weitgehend interoperabel mit EU-Handelspartnern, obwohl der Brexit jede rechtliche Verpflichtung zur Angleichung an den EU-ViDA-Rahmen aufhebt — eine bewusste Entscheidung, um die grenzüberschreitende Kompatibilität zu wahren.', NULL, 'Bestätigt' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Network model';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle", "Peppol à quatre coins (décentralisé)"], ["Autorité de contrôle", "Aucune"], ["Régime comparable", "Le modèle de première phase de la Belgique (2026)"]]', 'Cela maintient le Royaume-Uni largement interopérable avec les partenaires commerciaux de l''UE malgré le fait que le Brexit supprime toute obligation légale de s''aligner sur le cadre ViDA de l''UE — un choix délibéré pour préserver la compatibilité transfrontalière.', NULL, 'Confirmé' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Network model';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'Reporte en tiempo real', '[["En el lanzamiento de 2029", "No incluido"], ["Apoyo en la consulta", "El 63% de los encuestados estuvo de acuerdo con este enfoque"], ["Posibilidad futura", "No se descarta una futura capa de \"cinco esquinas\" de la HMRC"]]', 'El gobierno ha sido explícito en que el mandato de 2029 no exigirá alimentar datos de transacciones en vivo a la HMRC — pero ha dejado la puerta abierta a introducir alguna forma de reporte más adelante, una vez que la adopción de la facturación electrónica esté bien establecida.', NULL, 'Exclusión confirmada' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Real-time reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Echtzeitmeldung', '[["Beim Start 2029", "Nicht enthalten"], ["Konsultationsunterstützung", "63 % der Befragten stimmten diesem Fokus zu"], ["Künftige Möglichkeit", "Eine spätere \"Fünf-Ecken\"-HMRC-Schicht ist nicht ausgeschlossen"]]', 'Die Regierung hat ausdrücklich erklärt, dass die Vorgabe für 2029 keine Live-Übermittlung von Transaktionsdaten an die HMRC erfordern wird — hat aber die Tür für eine spätere Einführung einer Meldeform offengelassen, sobald sich die E-Invoicing-Einführung etabliert hat.', NULL, 'Bestätigter Ausschluss' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Real-time reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'Déclaration en temps réel', '[["Au lancement 2029", "Non incluse"], ["Soutien de la consultation", "63 % des répondants ont approuvé cette orientation"], ["Possibilité future", "Une future couche HMRC « à cinq coins » n''est pas exclue"]]', 'Le gouvernement a été explicite : l''obligation de 2029 n''exigera pas de transmettre des données de transaction en direct à la HMRC — mais a laissé la porte ouverte à l''introduction d''une forme de déclaration ultérieurement, une fois l''adoption de la facturation électronique bien établie.', NULL, 'Exclusion confirmée' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Real-time reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'Canales existentes del sector público', '[["NHS Supply Chain", "Puntos de Acceso Peppol certificados requeridos hoy"], ["Organismos de la Ley de Contratación Pública de 2023", "Deben aceptar facturas BS EN 16931"]]', 'Las autoridades locales conectadas a Peppol a través de la contratación del NHS o acuerdos G-Cloud existentes ya tienen una ventaja que la mayoría de las demás empresas británicas no tienen.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Existing public-sector channels';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Bestehende Kanäle des öffentlichen Sektors', '[["NHS Supply Chain", "Zertifizierte Peppol-Zugangspunkte heute erforderlich"], ["Stellen unter dem Public Procurement Act 2023", "Müssen BS-EN-16931-Rechnungen akzeptieren"]]', 'Lokale Behörden, die über die NHS-Beschaffung oder bestehende G-Cloud-Vereinbarungen mit Peppol verbunden sind, haben bereits einen Vorsprung, den die meisten anderen britischen Unternehmen nicht haben.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Existing public-sector channels';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'Canaux existants du secteur public', '[["NHS Supply Chain", "Points d''accès Peppol certifiés requis aujourd''hui"], ["Organismes du Public Procurement Act 2023", "Doivent accepter les factures BS EN 16931"]]', 'Les autorités locales connectées à Peppol via les achats du NHS ou des accords G-Cloud existants ont déjà une longueur d''avance que la plupart des autres entreprises britanniques n''ont pas.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Existing public-sector channels';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', 'Contexto de Making Tax Digital', '[["Programa más amplio", "La iniciativa más amplia de digitalización fiscal de la HMRC"], ["Ambición a largo plazo", "Declaraciones de IVA prellenadas"]]', 'La facturación electrónica se sitúa dentro de un impulso mucho más amplio de digitalización fiscal del Reino Unido. Incluso sin reporte en tiempo real hoy, los datos de facturación electrónica estructurados son exactamente el tipo de entrada que podría eventualmente alimentar declaraciones de IVA prellenadas en el futuro.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Making Tax Digital context';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', 'Kontext von Making Tax Digital', '[["Breiteres Programm", "Die umfassendere Initiative der HMRC zur Steuerdigitalisierung"], ["Langfristige Ambition", "Vorausgefüllte Umsatzsteuererklärungen"]]', 'E-Invoicing ist Teil eines viel größeren britischen Steuerdigitalisierungsvorstoßes. Selbst ohne heutige Echtzeitmeldung sind strukturierte E-Rechnungsdaten genau die Art von Eingabe, die künftig in vorausgefüllte Umsatzsteuererklärungen einfließen könnte.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Making Tax Digital context';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', 'Contexte de Making Tax Digital', '[["Programme plus large", "L''initiative plus large de la HMRC en matière de numérisation fiscale"], ["Ambition à long terme", "Déclarations de TVA pré-remplies"]]', 'La facturation électronique s''inscrit dans une démarche bien plus vaste de numérisation fiscale au Royaume-Uni. Même sans déclaration en temps réel aujourd''hui, les données de facturation électronique structurées sont exactement le type d''entrée qui pourrait à terme alimenter des déclarations de TVA pré-remplies.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'scope_transmission' AND dct.title = 'Making Tax Digital context';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', '📏 Implementación por fases según el tamaño de la empresa', NULL, NULL, 'Una introducción por fases comenzando por las empresas más grandes "sigue siendo una posibilidad real" según los comentarios del gobierno, pero no se ha confirmado en ningún sentido — el Presupuesto de 2026 debería resolver esto.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '📏 Phasing by business size';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', '📏 Staffelung nach Unternehmensgröße', NULL, NULL, 'Eine gestufte Einführung, beginnend mit größeren Unternehmen, "bleibt eine reale Möglichkeit" laut Regierungskommentaren, wurde aber in keiner Richtung bestätigt — der Haushalt 2026 dürfte dies klären.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '📏 Phasing by business size';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', '📏 Déploiement par phases selon la taille de l''entreprise', NULL, NULL, 'Une introduction par phases débutant par les grandes entreprises « reste une possibilité réelle » selon les commentaires gouvernementaux, mais n''a été confirmée dans aucun sens — le Budget 2026 devrait trancher ce point.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '📏 Phasing by business size';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', '🧾 Marco de sanciones', NULL, NULL, 'Todavía no se ha publicado ningún régimen de aplicación o sanciones. Es de esperar que esto llegue junto con la hoja de ruta de implementación completa en lugar de antes de ella.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🧾 Penalty framework';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', '🧾 Sanktionsrahmen', NULL, NULL, 'Es wurde noch kein Durchsetzungs- oder Sanktionsregime veröffentlicht. Erwarten Sie dies zusammen mit der vollständigen Umsetzungs-Roadmap, nicht davor.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🧾 Penalty framework';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', '🧾 Cadre des sanctions', NULL, NULL, 'Aucun régime d''application ou de sanctions n''a été publié. Attendez-vous à ce que cela arrive avec la feuille de route de mise en œuvre complète, et non avant.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🧾 Penalty framework';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', '🌍 La elección de alineación tras el Brexit', NULL, NULL, 'El Reino Unido no tiene obligación legal de seguir el marco ViDA de la UE tras el Brexit, y sin embargo ha elegido Peppol de todos modos — una apuesta deliberada por la interoperabilidad con sus principales socios comerciales frente a diseñar algo totalmente independiente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🌍 Post-Brexit alignment choice';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', '🌍 Die Ausrichtungsentscheidung nach dem Brexit', NULL, NULL, 'Das Vereinigte Königreich hat nach dem Brexit keine rechtliche Verpflichtung, dem EU-ViDA-Rahmen zu folgen, hat sich aber dennoch für Peppol entschieden — eine bewusste Wette auf Interoperabilität mit seinen größten Handelspartnern statt auf die Entwicklung einer völlig eigenständigen Lösung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🌍 Post-Brexit alignment choice';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', '🌍 Le choix d''alignement post-Brexit', NULL, NULL, 'Le Royaume-Uni n''a aucune obligation légale de suivre le cadre ViDA de l''UE après le Brexit, et a pourtant choisi Peppol malgré tout — un pari délibéré sur l''interopérabilité avec ses plus grands partenaires commerciaux plutôt que sur la conception de quelque chose de totalement indépendant.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🌍 Post-Brexit alignment choice';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'es', '🏥 El NHS como campo de pruebas', NULL, NULL, 'El mandato Peppol de NHS Supply Chain desde 2019 es en la práctica el proyecto piloto en vivo del Reino Unido para la implementación general de 2029 — las lecciones de la incorporación de proveedores del NHS probablemente están dando forma al diseño general de maneras que aún no se han hecho públicas.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🏥 NHS as the proving ground';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'de', '🏥 Der NHS als Testfeld', NULL, NULL, 'Die Peppol-Vorgabe von NHS Supply Chain seit 2019 ist praktisch der lebende Pilotversuch des Vereinigten Königreichs für die breitere Einführung 2029 — Erkenntnisse aus dem Onboarding von NHS-Lieferanten dürften das allgemeine Design auf noch nicht öffentlich gemachte Weise prägen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🏥 NHS as the proving ground';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label) SELECT dc.id, 'fr', '🏥 Le NHS comme terrain d''essai', NULL, NULL, 'L''obligation Peppol de NHS Supply Chain depuis 2019 est en pratique le pilote en direct du Royaume-Uni pour le déploiement général de 2029 — les enseignements tirés de l''intégration des fournisseurs du NHS façonnent probablement la conception générale de manières pas encore rendues publiques.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dc.section = 'penalties_related' AND dct.title = '🏥 NHS as the proving ground';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si suministra al NHS, prepárese para Peppol ahora en cualquier caso', 'Esta obligación ya existe con independencia del mandato más amplio de 2029 — un Punto de Acceso Peppol certificado a través de NHS Supply Chain no es opcional si está dentro del alcance hoy.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'If you supply the NHS, get Peppol-ready now regardless';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie den NHS beliefern, machen Sie sich unabhängig davon jetzt Peppol-bereit', 'Diese Pflicht besteht bereits unabhängig von der breiteren Vorgabe für 2029 — ein zertifizierter Peppol-Zugangspunkt über NHS Supply Chain ist nicht optional, wenn Sie heute im Anwendungsbereich sind.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'If you supply the NHS, get Peppol-ready now regardless';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous fournissez le NHS, préparez-vous à Peppol dès maintenant quoi qu''il arrive', 'Cette obligation existe déjà indépendamment de l''obligation plus large de 2029 — un point d''accès Peppol certifié via NHS Supply Chain n''est pas facultatif si vous relevez du champ d''application aujourd''hui.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'If you supply the NHS, get Peppol-ready now regardless';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Audite la preparación Peppol de su ERP', 'Dado que Peppol ya está confirmado como la red, compruebe si su sistema de contabilidad o ERP ya tiene conectividad Peppol integrada, o necesitaría un Punto de Acceso de terceros.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Audit your ERP''s Peppol readiness';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie die Peppol-Bereitschaft Ihres ERP', 'Da Peppol nun als Netzwerk bestätigt ist, prüfen Sie, ob Ihr Buchhaltungs- oder ERP-System bereits über eine Peppol-Anbindung verfügt oder einen externen Zugangspunkt benötigen würde.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Audit your ERP''s Peppol readiness';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Auditez la préparation Peppol de votre ERP', 'Peppol étant désormais confirmé comme réseau, vérifiez si votre système comptable ou ERP dispose déjà d''une connectivité Peppol intégrée, ou nécessiterait un point d''accès tiers.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Audit your ERP''s Peppol readiness';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Considere la facturación electrónica bilateral voluntaria ahora', 'Nada impide que dos socios comerciales acuerden intercambiar facturas electrónicas estructuradas hoy. Desarrollar esta capacidad desde ahora, aunque sea de manera informal, reduce el impacto del plazo de 2029.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Consider voluntary bilateral e-invoicing now';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ziehen Sie freiwillige bilaterale E-Rechnungsstellung jetzt in Betracht', 'Nichts hindert zwei Handelspartner daran, sich heute auf den Austausch strukturierter E-Rechnungen zu einigen. Diese Fähigkeit frühzeitig aufzubauen, auch informell, mildert den Schock der Frist 2029.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Consider voluntary bilateral e-invoicing now';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Envisagez la facturation électronique bilatérale volontaire dès maintenant', 'Rien n''empêche deux partenaires commerciaux de convenir aujourd''hui d''échanger des factures électroniques structurées. Développer ce muscle tôt, même de manière informelle, réduit le choc de l''échéance de 2029.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Consider voluntary bilateral e-invoicing now';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Esté muy atento al Presupuesto de 2026', 'Esta es la fecha más importante en el calendario de facturación electrónica del Reino Unido entre ahora y 2029 — los estándares técnicos, el modelo de acreditación y cualquier implementación por fases según el tamaño de la empresa se definirán aquí.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Watch Budget 2026 closely';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beobachten Sie den Haushalt 2026 genau', 'Dies ist das mit Abstand wichtigste Datum im britischen E-Invoicing-Kalender zwischen jetzt und 2029 — die technischen Standards, das Akkreditierungsmodell und eine etwaige Staffelung nach Unternehmensgröße werden hier festgelegt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Watch Budget 2026 closely';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Surveillez de près le Budget 2026', 'C''est la date la plus importante du calendrier de facturation électronique britannique entre maintenant et 2029 — les normes techniques, le modèle d''accréditation et tout déploiement par phases selon la taille de l''entreprise seront tous définis ici.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Watch Budget 2026 closely';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'No invierta en exceso todavía en un esquema específico', 'Dado que la elección entre un estándar internacional existente y un CIUS específico del Reino Unido sigue abierta, evite fijar suposiciones sobre requisitos exactos a nivel de campo hasta que se publique la hoja de ruta.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Don''t over-invest in a specific schema yet';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Investieren Sie noch nicht zu stark in ein bestimmtes Schema', 'Da die Wahl zwischen einem bestehenden internationalen Standard und einer UK-spezifischen CIUS noch offen ist, vermeiden Sie es, Annahmen über genaue feldbezogene Anforderungen fest einzuprogrammieren, bis die Roadmap vorliegt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Don''t over-invest in a specific schema yet';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'N''investissez pas encore trop dans un schéma spécifique', 'Le choix entre une norme internationale existante et un CIUS propre au Royaume-Uni restant ouvert, évitez de figer des hypothèses sur les exigences exactes au niveau des champs avant la publication de la feuille de route.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'United Kingdom' AND dst.title = 'Don''t over-invest in a specific schema yet';

